-- Esquema Supabase: Catalogo de Unidades Operativas (DRE y UGEL)
-- Fuente: C:/LEO/PERSONAL/MINEDU/REGION_UGEL.xlsx (251 filas · 26 regiones)
-- Idempotente: puede re-ejecutarse sin duplicar (on conflict id do update)
-- ==============================================================================

create table if not exists public.gestor_unidades (
  id text primary key,
  tenant_id text,
  parent_unit_id text references public.gestor_unidades(id) on delete set null,
  name text not null,
  code text not null,
  unit_type text not null default 'ugel',
  region text,
  macroregion text,
  address text,
  status text not null default 'active',
  metadata jsonb default '{}'::jsonb,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create unique index if not exists uq_gestor_unidades_code on public.gestor_unidades(code);
create index if not exists idx_gestor_unidades_region on public.gestor_unidades(region);
create index if not exists idx_gestor_unidades_type on public.gestor_unidades(unit_type);
create index if not exists idx_gestor_unidades_tenant on public.gestor_unidades(tenant_id);

-- RLS permisiva, misma convencion de 01_gestor_cronograma.sql
alter table public.gestor_unidades enable row level security;
drop policy if exists "Permitir todo en gestor_unidades" on public.gestor_unidades;
create policy "Permitir todo en gestor_unidades"
  on public.gestor_unidades
  for all
  using (true)
  with check (true);

-- Semilla del catalogo DRE/UGEL (23 DRE · 228 UGEL = 251 unidades, 26 regiones)
on conflict (id) do update
  set name = excluded.name,
      code = excluded.code,
      unit_type = excluded.unit_type,
      region = excluded.region,
      status = excluded.status,
      metadata = excluded.metadata,
      updated_at = now();
